-- 20_SCM_ADM_PROC_M.sql — [E20260929-DMF0082SAVETXN] SAVE 파라미터 메타 (사내 현행 18행 · IN 17 = CLOB) · 멱등 MERGE · 빌드 2026-09-30 00:14
-- ⚠ 10·11 적용(SP 가 CLOB 선언) 이후에 실행. 순서가 바뀌면 BE 가 CLOB 으로 바인딩하는데 SP 는 VARCHAR2 인 구간이 생긴다.
MERGE INTO SCM_MGR.SCM_ADM_PROC_M T
USING (
  SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'activeFlag' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 1 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'divisionId' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 2 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'projectCode' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 3 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'endCustomer' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 4 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'scmSiteId' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 5 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'itemId' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 6 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'domExp' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 7 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'fcstType' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 8 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'incoterms' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 9 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'measure' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 10 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'plantSite' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 11 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'cellProdSiteId' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 12 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'yyyymmdd' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 13 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'currency' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 14 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'qty' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 15 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'createdBy' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 16 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'asFromSite' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 17 SORT_ORD FROM DUAL
  UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' PROC_NM, 'o_rc1' COL_NM, 'CURSOR' DATA_TP_CD, 'OUT' COL_TP_CD, 18 SORT_ORD FROM DUAL
) S
ON (T.PROC_NM = S.PROC_NM AND T.COL_NM = S.COL_NM AND T.COL_TP_CD = S.COL_TP_CD)
WHEN MATCHED THEN UPDATE SET T.DATA_TP_CD = S.DATA_TP_CD, T.SORT_ORD = S.SORT_ORD,
                             T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
   WHERE T.DATA_TP_CD <> S.DATA_TP_CD OR T.SORT_ORD <> S.SORT_ORD
WHEN NOT MATCHED THEN INSERT (PROC_NM, COL_NM, DATA_TP_CD, COL_TP_CD, SORT_ORD, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES (S.PROC_NM, S.COL_NM, S.DATA_TP_CD, S.COL_TP_CD, S.SORT_ORD, 'admin', SYSDATE, 'admin', SYSDATE);
COMMIT;

SELECT COL_NM, DATA_TP_CD, COL_TP_CD, SORT_ORD FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA' ORDER BY SORT_ORD;
-- 기대: 18행 · IN 17 = CLOB · o_rc1 = CURSOR/OUT
